import React from 'react';
import { Box, useMediaQuery, useTheme } from '@mui/material';
import { useLocation } from 'react-router-dom';
import ChatSystem from '../components/ChatSystem';

const MessagesPage = () => {
  const location = useLocation();
  const theme = useTheme();
  const isDesktop = useMediaQuery(theme.breakpoints.up('lg')); // >= 1200px
  const isTablet = useMediaQuery(theme.breakpoints.between('md', 'lg')); // 900-1199px
  const { recipientId, recipientName, recipientAvatar, conversationId } = location.state || {};

  // Match global layout spacing (Navbar + MobileBottomNav) and account for safe-area insets.
  // Desktop uses sidebar layout (no top/bottom nav).
  const topNavHeight = isDesktop ? 0 : (isTablet ? 70 : 80);
  const bottomNavHeight = isDesktop ? 0 : 80;

  return (
    <Box sx={{
      height: `calc(100dvh - ${topNavHeight}px - ${bottomNavHeight}px - env(safe-area-inset-top) - env(safe-area-inset-bottom))`,
      minHeight: 0,
      display: 'flex',
      overflow: 'hidden'
    }}>
      <ChatSystem
        recipientId={recipientId}
        recipientName={recipientName}
        recipientAvatar={recipientAvatar}
        initialConversationId={conversationId}
      />
    </Box>
  );
};

export default MessagesPage;
